$WshShell = New-Object -ComObject WScript.Shell
$Paths = @([Environment]::GetFolderPath("Desktop"), [Environment]::GetFolderPath("StartMenu"))
foreach ($Path in $Paths) {
    if (Test-Path $Path) {
        Get-ChildItem -Path $Path -Recurse -Filter *.lnk -ErrorAction SilentlyContinue | ForEach-Object {
            try {
                $Shortcut = $WshShell.CreateShortcut($_.FullName)
                $Target = $Shortcut.TargetPath
                if ($Target -match '^[a-zA-Z]:\\' -and -not (Test-Path -LiteralPath $Target)) {
                    Write-Output "BROKEN|$($_.FullName)|$Target"
                }
            } catch {}
        }
    }
}

$WshShell = New-Object -ComObject WScript.Shell
$Paths = @("C:\Users\Public\Desktop", "C:\ProgramData\Microsoft\Windows\Start Menu")
foreach ($Path in $Paths) {
    if (Test-Path $Path) {
        Get-ChildItem -Path $Path -Recurse -Filter *.lnk -ErrorAction SilentlyContinue | ForEach-Object {
            try {
                $Shortcut = $WshShell.CreateShortcut($_.FullName)
                $Target = $Shortcut.TargetPath
                if ($Target -match '^[a-zA-Z]:\\' -and -not (Test-Path -LiteralPath $Target)) {
                    Write-Output "BROKEN|$($_.FullName)|$Target"
                }
            } catch {}
        }
    }
}

$Shortcuts = @(
    "C:\Users\zam_z\AppData\Roaming\Microsoft\Windows\Start Menu\Programs\Exam Environment.lnk",
    "C:\Users\Public\Desktop\EA.lnk",
    "C:\Users\Public\Desktop\Steam.lnk",
    "C:\ProgramData\Microsoft\Windows\Start Menu\Programs\EA\App Recovery.lnk",
    "C:\ProgramData\Microsoft\Windows\Start Menu\Programs\EA\EA app Updater.lnk",
    "C:\ProgramData\Microsoft\Windows\Start Menu\Programs\EA\EA Error Reporter.lnk",
    "C:\ProgramData\Microsoft\Windows\Start Menu\Programs\EA\EA Updater.lnk",
    "C:\ProgramData\Microsoft\Windows\Start Menu\Programs\EA\EA.lnk",
    "C:\ProgramData\Microsoft\Windows\Start Menu\Programs\Steam\Steam.lnk"
)

foreach ($Shortcut in $Shortcuts) {
    if (Test-Path -LiteralPath $Shortcut) {
        Remove-Item -LiteralPath $Shortcut -Force
        Write-Output "Deleted: $Shortcut"
    }
}

# Cleanup empty folders
$FoldersToCheck = @(
    "C:\ProgramData\Microsoft\Windows\Start Menu\Programs\EA",
    "C:\ProgramData\Microsoft\Windows\Start Menu\Programs\Steam"
)

foreach ($Folder in $FoldersToCheck) {
    if ((Test-Path $Folder) -and (Get-ChildItem -Path $Folder).Count -eq 0) {
        Remove-Item -Path $Folder -Force
        Write-Output "Deleted empty folder: $Folder"
    }
}

$Paths = @(
    "C:\Users\zam_z\Desktop",
    "C:\Users\zam_z\Documents",
    "C:\Users\zam_z\Downloads",
    "C:\Users\zam_z\AppData\Local",
    "C:\Users\zam_z\AppData\Roaming",
    "C:\Program Files",
    "C:\Program Files (x86)"
)

function Get-EmptyFolders($Path) {
    if (Test-Path $Path) {
        Get-ChildItem -Path $Path -Recurse -Directory -ErrorAction SilentlyContinue | Where-Object {
            (Get-ChildItem -Path $_.FullName -Force).Count -eq 0
        } | Select-Object -ExpandProperty FullName
    }
}

foreach ($P in $Paths) {
    $Empty = Get-EmptyFolders $P
    if ($Empty) {
        foreach ($Folder in $Empty) {
            Write-Output "EMPTY|$Folder"
        }
    }
}

$FoldersToDelete = @(
    "C:\Users\zam_z\Documents\Marce\App consolidador\dist",
    "C:\Users\zam_z\Documents\Marce\pdf-consolidator\pdf-consolidator\dist",
    "C:\Users\zam_z\Documents\Marce\Version 1.1\dist",
    "C:\Users\zam_z\AppData\Local\Exam Environment",
    "C:\Users\zam_z\AppData\Local\Electronic Arts",
    "C:\Program Files\Adobe",
    "C:\Program Files\Tesseract-OCR\tessdata\script",
    "C:\Program Files (x86)\Adobe",
    "C:\Program Files (x86)\Google"
)

foreach ($Folder in $FoldersToDelete) {
    if (Test-Path $Folder) {
        try {
            Remove-Item -Path $Folder -Recurse -Force -ErrorAction SilentlyContinue
            Write-Output "Deleted: $Folder"
        } catch {
            Write-Output "Failed to delete: $Folder"
        }
    }
}

# Recursively clean up empty folders in specific user subdirectories
$CleanupRoots = @(
    "C:\Users\zam_z\Documents\Marce",
    "C:\Users\zam_z\Documents\Javascript-Algorithms"
)

foreach ($Root in $CleanupRoots) {
    if (Test-Path $Root) {
        Get-ChildItem -Path $Root -Recurse -Directory | Sort-Object FullName -Descending | ForEach-Object {
            if ((Get-ChildItem -Path $_.FullName -Force).Count -eq 0) {
                Remove-Item -Path $_.FullName -Force
                Write-Output "Deleted empty subfolder: $($_.FullName)"
            }
        }
    }
}

$Paths = @("C:\Users\zam_z\Documents", "C:\Users\zam_z\AppData\Local", "C:\Users\zam_z\AppData\Roaming")

foreach ($P in $Paths) {
    if (Test-Path $P) {
        Get-ChildItem -Path $P -Recurse -Directory -ErrorAction SilentlyContinue | ForEach-Object {
            $allFiles = Get-ChildItem -Path $_.FullName -Force -ErrorAction SilentlyContinue
            $visibleFiles = Get-ChildItem -Path $_.FullName -ErrorAction SilentlyContinue

            # If it has files, but NO visible files, it only contains hidden items.
            if ($allFiles.Count -gt 0 -and $visibleFiles.Count -eq 0) {
                Write-Output "HIDDEN_ONLY|$($_.FullName)|$($allFiles.Name -join ', ')"
            }
        }
    }
}

# Checking Registry Run keys
$keys = @(
    "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\Run",
    "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\RunOnce",
    "HKCU:\Software\Microsoft\Windows\CurrentVersion\Run",
    "HKCU:\Software\Microsoft\Windows\CurrentVersion\RunOnce"
)

foreach ($key in $keys) {
    if (Test-Path $key) {
        Write-Output "--- Key: $key ---"
        Get-ItemProperty $key | Select-Object -Property * -ExcludeProperty PSPath,PSParentPath,PSChildName,PSDrive,PSProvider | Format-List
    }
}

# Checking Startup Folders
$startupPaths = @(
    "C:\ProgramData\Microsoft\Windows\Start Menu\Programs\Startup",
    "$env:APPDATA\Microsoft\Windows\Start Menu\Programs\Startup"
)

foreach ($path in $startupPaths) {
    Write-Output "--- Folder: $path ---"
    Get-ChildItem $path -Force | Select-Object Name, Length, LastWriteTime
}

Get-Process | Where-Object { $_.Path -ne $null } | Select-Object Name, Path | Where-Object { 
    $_.Path -match "Temp" -or 
    $_.Path -match "Users\\Public" -or 
    ($_.Path -notmatch "^C:\\Windows" -and $_.Path -notmatch "^C:\\Program Files")
} | Format-Table -AutoSize

# Remove Steam and EA entries from Current User Run key
$RunKey = "HKCU:\Software\Microsoft\Windows\CurrentVersion\Run"
$ItemsToRemove = @("Steam", "EADM")

foreach ($Item in $ItemsToRemove) {
    if ((Get-ItemProperty -Path $RunKey -Name $Item -ErrorAction SilentlyContinue)) {
        Remove-ItemProperty -Path $RunKey -Name $Item -Force
        Write-Output "Removed: $Item from $RunKey"
    }
}
